def stats(v):
 v=np.asarray(v);v=v[np.isfinite(v)];return dict(n=len(v),median=float(np.median(v)),p95=float(np.percentile(v,95)),max=float(v.max()))
def main():
 result=read(RUN/'result.json');terminal=read(RUN/'terminal-evidence.json');assert result['status']=='completed' and terminal['implementation']==codehash()
 for p,h in terminal['files'].items():assert digest(RUN/p)==h
 for p,h in read(I/'manifest.json')['files'].items():assert digest(I/p)==h
 mesh=arrays(I/'mesh.npz');old=arrays(OLDM);g=arrays(G);ng=arrays(I/'geometry.npz');mat=arrays(I/'material.npz');state,u,_=restore(RUN/'frame-000',result['contract']);ou=arrays(OLDU)['u'];assert np.array_equal(state['h'],mesh['thickness']) and np.array_equal(state['A'],mat['A']);REPORT.mkdir(exist_ok=False)
 x,y=g['x'],g['y'];X,Y=np.meshgrid(x,y);Axy=np.array([-2139.7096677023073,3159517.8405094133]);rr,cc=238,222
 ospeed=np.linalg.norm(ou[:,-1],axis=1);nspeed=np.linalg.norm(u[:,-1],axis=1);d,newidx=cKDTree(mesh['xy']).query(old['xy']);assert np.max(d)<1e-7;peak=int(ospeed.argmax());npk=int(nspeed.argmax());assert np.array_equal(mat['A'][newidx],arrays(MAT)['A'])
 node_dist=np.linalg.norm(old['xy']-Axy,axis=1);node_regions={'within240m':node_dist<=240,'within500m':node_dist<=500,'all_original_nodes':np.ones(len(node_dist),bool)}
 H0=g['thickness_m'];H1=ng['thickness_m'];S0=g['surface_elevation_m'];S1=ng['surface_elevation_m'];B0=g['bed_elevation_m'];m0=g['valid_mask'].astype(bool);m1=ng['valid_mask'].astype(bool);common=m0&m1
 V0=np.full(H0.shape,np.nan);V1=V0.copy();V0[old['pixel_rows'],old['pixel_cols']]=ospeed[old['pixel_center_nodes']];V1[mesh['pixel_rows'],mesh['pixel_cols']]=nspeed[mesh['pixel_center_nodes']]
 def slope(S):
  gy,gx=np.gradient(S.astype(float),y,x);return np.degrees(np.arctan(np.hypot(gx,gy)))
 sl0=slope(S0);sl1=slope(S1);pr=read(I/'summary.json');rad=np.hypot(X-Axy[0],Y-Axy[1]);regions={}
 for name,m in node_regions.items():regions[name]=dict(old_speed=stats(ospeed[m]),new_speed_same_nodes=stats(nspeed[newidx[m]]))
 gridregions={}
 for radius in [240,500]:
  m=common&(rad<=radius);gridregions[str(radius)]=dict(old_H=stats(H0[m]),new_H=stats(H1[m]),old_slope=stats(sl0[m]),new_slope=stats(sl1[m]),common_pixels=int(m.sum()))
 summary=dict(status='completed-one-outlet-hypothesis-control',new_BP_solves=1,geometry=pr,momentum=result['momentum'],old_A=dict(node=peak,xy=old['xy'][peak].tolist(),old_speed_m_year=float(ospeed[peak]),new_speed_same_node_m_year=float(nspeed[newidx[peak]]),old_node_H_m=float(old['thickness'][peak]),new_node_H_m=float(mesh['thickness'][newidx[peak]]),bed_change_m=float(mesh['bed'][newidx[peak]]-old['bed'][peak]),material_bitwise_unchanged=True),nearest_A_grid=dict(row=rr,col=cc,old_H_m=float(H0[rr,cc]),new_H_m=float(H1[rr,cc]),old_surface_slope_deg=float(sl0[rr,cc]),new_surface_slope_deg=float(sl1[rr,cc]),old_north_cell_S_drop_m=float(S0[rr,cc]-S0[rr-1,cc]),new_north_cell_S_drop_m=float(S1[rr,cc]-S1[rr-1,cc])),new_global_peak=dict(speed_m_year=float(nspeed[npk]),xy=mesh['xy'][npk].tolist(),H_m=float(mesh['thickness'][npk]),material_extended=bool(not mat['exact'][npk])),fixed_node_regions=regions,fixed_grid_regions=gridregions,volume_change_percent=100*(pr['new_volume_m3']/pr['old_volume_m3']-1),positive_area_change_percent=100*(m1.sum()/m0.sum()-1),checks=dict(all_old_nodes_retained=True,all_common_node_material_bitwise=True,unchanged_source_hash=digest(G),sealed_state_H_A_exact=True,basal_no_slip=bool(np.all(u[:,0]==0)),finite_velocity=bool(np.isfinite(u).all())),limitations=['Terrain-guided west outlet is a hypothesis,not independently reconstructed LIA terminus.','Candidate volume/support differ substantially;lower speed is not scientific validation.','Some boundary corner bed averages change when new positive cells appear;source bed raster is unchanged;old A bed unchanged is separately reported.','Frozen A is extended to added nodes only;all original nodes preserve A exactly.','Original baseline is reused;new1D constraints use original tau rounded as recorded in production ledger;other old-source anchor samples are frozen.'])
 write_json(REPORT/'summary.json',summary);np.savez_compressed(REPORT/'comparison-fields.npz',x=x,y=y,old_H=H0,new_H=H1,old_S=S0,new_S=S1,old_speed=V0,new_speed=V1,old_slope=sl0,new_slope=sl1,common=common,old_mask=m0,new_mask=m1)
 plt.rcParams.update({'font.family':FontProperties(fname='C:/Windows/Fonts/msyh.ttc').get_name(),'axes.unicode_minus':False,'font.size':10})
 fig,axs=plt.subplots(2,3,figsize=(15,10),facecolor='#f6f8fc');xx=(X-Axy[0])/1000;yy=(Y-Axy[1])/1000;route=arrays(I/'profile.npz')['xy'];oldroute=arrays(CON/'connector-0.npz')['xy'];lim=(-2.2,2.0,-2.1,3.2)
 layers=[(H0,m0,'原重建冰厚','viridis',Normalize(0,400),'m'),(H1,m1,'独立出口假设下的冰厚','viridis',Normalize(0,400),'m'),(H1-H0,common,'冰厚变化（新 − 原）','RdBu_r',TwoSlopeNorm(vmin=-400,vcenter=0,vmax=400),'m'),(V0,m0,'原 BP 冰速','turbo',LogNorm(.01,3500),'m/年'),(V1,m1,'新 BP 冰速','turbo',LogNorm(.01,3500),'m/年'),(sl1-sl0,common,'冰面坡度变化（新 − 原）','RdBu_r',TwoSlopeNorm(vmin=-45,vcenter=0,vmax=45),'°')]
 for ax,(F,mask,title,cmap,norm,unit) in zip(axs.ravel(),layers):
  im=ax.pcolormesh(xx,yy,np.ma.masked_where(~mask|~np.isfinite(F),F),shading='nearest',cmap=cmap,norm=norm,rasterized=True);fig.colorbar(im,ax=ax,shrink=.75,pad=.025,label=unit);ax.scatter(0,0,marker='*',s=95,color='#f93854',edgecolors='white',linewidth=.7,zorder=5);ax.set(xlim=lim[:2],ylim=lim[2:],aspect='equal',title=title,xlabel='相对原高速点东西距离（km）',ylabel='南北距离（km）');ax.set_facecolor('#e9edf3')
  if ax in [axs[0,0],axs[1,0]]:ax.plot((oldroute[:,0]-Axy[0])/1000,(oldroute[:,1]-Axy[1])/1000,color='white',lw=1,ls='--')
  if ax in [axs[0,1],axs[1,1]]:ax.plot((route[:,0]-Axy[0])/1000,(route[:,1]-Axy[1])/1000,color='white',lw=1,ls='--')
 fig.suptitle('连接关系对照 · 原高速点保持在同一位置比较',fontsize=20,x=.055,ha='left',y=.98);fig.text(.055,.935,'红星 = 原高速点 A；白虚线 = 原连接段 / 新独立出口流线。颜色范围前后一致；速度采用对数色标。',color='#536175',fontsize=11);fig.subplots_adjust(left=.055,right=.96,top=.89,bottom=.07,hspace=.25,wspace=.25);fig.savefig(REPORT/'comparison.png',dpi=150);plt.close(fig)
 # Same section as the previous user's figure, with unchanged bed and equal axes.
 rows=np.arange(rr-32,rr+33);off=y[rows]-y[rr];order=np.argsort(off);rows=rows[order];off=off[order];fig,ax=plt.subplots(figsize=(10,8),facecolor='#f6f8fc');ax.plot(off,S0[rows,cc],label='原冰面',color='#cc5264',lw=2);ax.plot(off,S1[rows,cc],label='新冰面（独立出口假设）',color='#087fa2',lw=2);ax.plot(off,B0[rows,cc],label='同一冰床',color='#77634c',lw=2);ax.fill_between(off,B0[rows,cc],S1[rows,cc],color='#bde8f4',alpha=.6);ax.axvline(0,color='#999',ls=':');ax.set_aspect('equal',adjustable='box');ax.set(xlabel='距 A′ 的南北距离（m；正值向北）',ylabel='海拔（m）',title='原高速点附近：同一剖面的修正前后冰面');ax.legend();ax.grid(alpha=.2);fig.tight_layout();fig.savefig(REPORT/'profile.png',dpi=150);plt.close(fig)
 A=summary['old_A'];Q=summary['nearest_A_grid'];P=summary['new_global_peak'];md=f'''# 一次独立出口假设对照\n\n原高速点同一节点：{A['old_speed_m_year']:.2f} → {A['new_speed_same_node_m_year']:.2f} m/年。该点节点冰厚 {A['old_node_H_m']:.2f} → {A['new_node_H_m']:.2f} m，冰床变化 {A['bed_change_m']:.9f} m，材料参数逐值不变。最近源网格冰面坡度 {Q['old_surface_slope_deg']:.2f}° → {Q['new_surface_slope_deg']:.2f}°。\n\n新全场峰值 {P['speed_m_year']:.2f} m/年，位于 {P['xy']}。总冰量变化 {summary['volume_change_percent']:.2f}%，正冰厚计算面积变化 {summary['positive_area_change_percent']:.2f}%。原 LIA 外轮廓未改变；新增正冰厚单元由重新分布产生。\n\n这表明原高速点对支流下游连接条件敏感，尚不能证明新出口就是实际古冰川出口，或新冰厚已准确。原厚冰峰值显著改变时，冰面坡度仍可能很陡；应同时解释冰厚和冰速。\n\n西北出口取自原冰床地形路径与原 LIA 边界交点，仅为预先登记的几何假设。未修改冰床栅格、剪应力、形状因子或既有节点材料参数。其他支流的原采样约束保留，内部没有人为设置零冰厚。新网格边界角点平均冰床有局部变化，新增节点材料采用最近原节点外延，均在摘要中量化。原输入和已完成基线没有重跑。\n\n一次 BP 求解收敛，残差 {result['momentum']['relative_residual']:.3g}；每次 Newton 迭代和最终 H、A、u 已封存并校验。没有时间演化、流速裁剪、参数调优或科学验收。\n''';(REPORT/'analysis.md').write_text(md,encoding='utf-8')
 html=f'''<!doctype html><html lang="zh"><meta charset="utf-8"><title>独立出口对照</title><style>body{{background:#f6f8fc;color:#203047;font:17px 'Microsoft YaHei',sans-serif;margin:0}}main{{max-width:1300px;margin:auto;padding:25px}}img{{width:100%}}p{{line-height:1.8}}.cards{{display:flex;gap:15px;flex-wrap:wrap}}.card{{background:white;padding:20px;flex:1;border-radius:12px}}b{{display:block;font-size:27px;margin-top:12px}}</style><main><h1>独立出口假设：连接改变的影响</h1><p>保留原冰床栅格、塑性参数与冻结 BP 材料，将 0 号支流改为西北侧独立出口。一次固定几何对照，未进行时间演化；该出口尚无独立古冰川末端证据。</p><div class="cards"><div class="card">原高速点，同一节点（m/年）<b>{A['old_speed_m_year']:.1f} → {A['new_speed_same_node_m_year']:.1f}</b></div><div class="card">T 点冰厚（m）<b>{pr['old_T_H_m']:.1f} → {pr['new_T_grid_H_m']:.1f}</b></div><div class="card">总冰量变化<b>{summary['volume_change_percent']:.1f}%</b></div></div><img src="comparison.png"><img src="profile.png"><p>新全场最高冰速 {P['speed_m_year']:.1f} m/年。原高速点附近坡度 {Q['old_surface_slope_deg']:.1f}° → {Q['new_surface_slope_deg']:.1f}°。降低冰速不等于几何已经正确；体积变化及候选出口仍需地貌约束。</p><p>新增节点材料外延最大 {pr['maximum_material_extension_m']:.1f} m；所有原网格节点的材料逐值不变。原高速点冰床变化 {A['bed_change_m']:.1f} m。<a href="summary.json">查看数值与边界说明</a></p></main></html>''';(REPORT/'index.html').write_text(html,encoding='utf-8');write_json(REPORT/'delivery.json',dict(files={p.name:digest(p) for p in REPORT.iterdir() if p.is_file()},new_simulations=0));print(json.dumps(summary,ensure_ascii=False))
if __name__=='__main__':main()
